// Replays a scripted control session, recorded exactly as demo/motor_bridge.py streams it, through
// the live mirror. The fixture is generated by frontend/scripts/live_mirror_fixture.py from the
// unmodified control/ pipeline and the Python receiver oracle. Synthetic frames, test key.

import { readFileSync } from 'node:fs'
import { gunzipSync } from 'node:zlib'
import { describe, expect, it } from 'vitest'
import { LiveMirror, decodeDatagram, hexToBytes } from './liveMirror.js'
import { CORRIDOR_WORLD } from '../sim/worldModel.js'

const lines = gunzipSync(readFileSync(new URL('./__fixtures__/live-session.jsonl.gz', import.meta.url)))
  .toString('utf8').trim().split('\n').map((line) => JSON.parse(line))
const [hello, ...records] = lines

function replay(mirrorHello = hello, onRecord = () => {}) {
  const mirror = new LiveMirror(mirrorHello)
  for (const record of records) {
    const before = { pose: mirror.pose, torque: mirror.receiver.motorsHaveTorque() }
    const result = mirror.apply(record)
    onRecord(record, result, before, mirror)
  }
  return mirror
}

describe('live mirror of the software-only control run', () => {
  it('is a software-only hello for the labelled test key', () => {
    expect(hello).toMatchObject({ type: 'hello', software_only: true, controller_id: 'laptop' })
    expect(hexToBytes(hello.key_hex)).toHaveLength(hello.key_hex.length / 2)
  })

  it('reaches the same verdict as the Python oracle on every call', () => {
    const mirror = replay()
    expect(mirror.applied).toBe(records.length)
    expect(mirror.disagreements).toEqual([])
    expect(mirror.agreed).toBe(records.length)
  })

  it('judges every forwarded datagram itself, including the forged one', () => {
    const outcomes = new Set()
    let forged = null
    replay(hello, (record, result, _before, mirror) => {
      if (record.op.op !== 'datagram') return
      outcomes.add(result)
      if (result === 'invalid_stop') forged = { record, view: mirror.view() }
    })
    expect(outcomes).toEqual(new Set(['accepted_start', 'accepted_rearm', 'accepted_motion', 'accepted_stop', 'invalid_stop']))
    expect(forged).not.toBeNull()
    // Forwarded unfiltered: the forged datagram is still there, and still names its altered MAC.
    expect(JSON.parse(decodeDatagram(forged.record.op.raw_b64)).mac).toMatch(/^[0-9a-f]{64}$/)
    expect(forged.view.lastRejection.outcome).toBe('invalid_stop')
    expect(forged.view.torque).toBe(false) // the refusal commands safe output
  })

  it('moves the rover only on output this receiver applied, and never on a refused datagram', () => {
    let movedWithoutTorque = false
    let movedOnRefusal = false
    replay(hello, (record, result, before, mirror) => {
      const moved = mirror.pose !== before.pose
      if (moved && !before.torque) movedWithoutTorque = true
      if (record.op.op === 'datagram' && !String(result).startsWith('accepted_') && moved) movedOnRefusal = true
    })
    expect(movedWithoutTorque).toBe(false)
    expect(movedOnRefusal).toBe(false)
  })

  it('drives the corridor rover forward and ends halted by the watchdog after the link drop', () => {
    const mirror = replay()
    const view = mirror.view()
    expect(view.pose.x - CORRIDOR_WORLD.spawn.x).toBeGreaterThan(1)
    expect(view.counts.accepted).toBeGreaterThan(100)
    expect(view.torque).toBe(false)
    expect(view.haltReason).toBe('watchdog')
  })

  it('a mirror holding a different key accepts nothing and never moves', () => {
    const wrong = { ...hello, key_hex: '00'.repeat(hello.key_hex.length / 2) }
    const mirror = replay(wrong)
    expect(mirror.counts.accepted).toBe(0)
    expect(mirror.pose).toEqual(CORRIDOR_WORLD.spawn)
    expect(mirror.disagreements.length).toBeGreaterThan(0)
  })

  it('refuses an out-of-order or non-software-only stream instead of guessing', () => {
    const mirror = new LiveMirror(hello)
    expect(() => mirror.apply(records[1])).toThrow(/out of order/)
    expect(() => new LiveMirror({ ...hello, software_only: false })).toThrow()
  })
})
